-- Indexes for the paginated list endpoints (written by hand, not generated by prisma migrate dev).
-- Each one matches the WHERE and ORDER BY of the list query, so Postgres reads the page
-- straight from the index instead of sorting every row of the user.

-- GET /api/movements: ORDER BY date DESC, created_at DESC, id DESC WHERE user_id = ? AND deleted_at IS NULL
CREATE INDEX "idx_movements_user_date_active" ON "movements"("user_id", "date" DESC, "created_at" DESC, "id" DESC) WHERE (deleted_at IS NULL);

-- GET /api/bank-accounts: ORDER BY bank_name, created_at, id WHERE user_id = ? AND deleted_at IS NULL
CREATE INDEX "idx_bank_accounts_user_list" ON "bank_accounts"("user_id", "bank_name", "created_at", "id") WHERE (deleted_at IS NULL);

-- GET /api/goals: ORDER BY end_date, created_at, id WHERE user_id = ? AND deleted_at IS NULL
CREATE INDEX "idx_goals_user_list" ON "goals"("user_id", "end_date", "created_at", "id") WHERE (deleted_at IS NULL);
